<script setup lang="ts">
import {ref,nextTick,onMounted,onUnmounted,useId} from 'vue'
const props=defineProps<{label:string}>(),id=useId(),root=ref<HTMLDetailsElement|null>(null),panel=ref<HTMLElement|null>(null),open=ref(false),position=ref({left:'0px',top:'0px',maxHeight:'320px'})
let disposed=false
function close(restore=false){if(!root.value?.open)return;root.value.open=false;open.value=false;if(restore)root.value.querySelector('summary')?.focus()}
function place(){if(!root.value?.open||!panel.value)return;const trigger=root.value.querySelector('summary')!.getBoundingClientRect(),rect=panel.value.getBoundingClientRect(),viewport=window.visualViewport,top=viewport?.offsetTop||0,left=viewport?.offsetLeft||0,width=viewport?.width||innerWidth,height=viewport?.height||innerHeight,bottom=top+height-12,below=bottom-trigger.bottom-8,above=trigger.top-top-20,down=below>=Math.min(rect.height,220)||below>=above,available=Math.max(44,down?below:above);position.value={left:Math.max(left+12,Math.min(trigger.right-rect.width,left+width-rect.width-12))+'px',top:(down?trigger.bottom+8:Math.max(top+12,trigger.top-8-Math.min(rect.height,available)))+'px',maxHeight:available+'px'}}
async function toggled(){open.value=!!root.value?.open;if(open.value){await nextTick();if(!disposed)place()}}
function keydown(e:KeyboardEvent){if(!root.value?.open)return;if(e.key==='Escape'){e.preventDefault();e.stopPropagation();close(true)}else if(e.key==='ArrowDown'&&e.target===root.value.querySelector('summary')){e.preventDefault();panel.value?.querySelector<HTMLElement>('button:not(:disabled),a[href],input:not(:disabled)')?.focus()}}
function outside(e:PointerEvent){if(e.target instanceof Node&&!root.value?.contains(e.target))close()}
function action(e:MouseEvent){const target=e.target instanceof Element?e.target.closest('button,a[href]'):null;if(target&&!target.hasAttribute('disabled')){close();void nextTick(()=>{if(!disposed&&!document.querySelector('[role="dialog"][aria-modal="true"]'))root.value?.querySelector('summary')?.focus()})}}
onMounted(()=>{document.addEventListener('pointerdown',outside);document.addEventListener('keydown',keydown,true);window.addEventListener('resize',place);window.addEventListener('scroll',place,true);window.visualViewport?.addEventListener('resize',place)})
onUnmounted(()=>{disposed=true;document.removeEventListener('pointerdown',outside);document.removeEventListener('keydown',keydown,true);window.removeEventListener('resize',place);window.removeEventListener('scroll',place,true);window.visualViewport?.removeEventListener('resize',place)})
</script>
<template><details ref="root" class="action-menu" @toggle="toggled"><summary :aria-label="props.label" :aria-controls="id" :aria-expanded="open"><slot name="trigger"/></summary><div v-show="open" ref="panel" :id="id" :inert="!open" :style="position" class="action-menu-panel" :aria-label="props.label" role="group" @click="action"><slot/></div></details></template>
<style scoped>
.action-menu{position:relative}.action-menu summary{cursor:pointer;min-height:44px;min-width:44px;display:grid;place-items:center;color:var(--quiet);padding:10px;border:1px solid var(--edge);border-radius:12px;list-style:none}.action-menu summary::-webkit-details-marker{display:none}.action-menu[open] summary{background:var(--wash);color:var(--accent)}.action-menu-panel{position:fixed;z-index:45;display:grid;gap:6px;width:min(220px,calc(100vw - 24px));overflow:auto;overscroll-behavior:contain;padding:8px;border:1px solid var(--edge);border-radius:12px;background:var(--canvas);box-shadow:0 8px 24px color-mix(in srgb,var(--ink) 10%,transparent)}.action-menu-panel :deep(button),.action-menu-panel :deep(a){min-height:44px;min-width:0;text-align:left;justify-content:start}.action-menu-panel :deep(.final-text-link){padding:10px}
</style>
